#pragma once
// The ESP8266 TLS trust policy: WHICH roots the build carries, what each one is for, and when a
// validated session may be opened at all. Pure C++ (no Arduino, no BearSSL, no clock of its own),
// so `pio test -e native` pins the rules instead of a comment - the compiled certificate blob
// itself lives in src/esp8266/tls_anchors.h, generated by tools/gen_tls_anchors.py.
//
// Why this is a policy and not just a list: the ESP8266 pays for every anchor in heap for the
// whole boot (measured: 6 anchors = 7,704 B free heap and 9,136 B of the largest contiguous block),
// so the set has to be the minimum that still validates every chain this firmware can meet, and the
// decision to validate must be refusable - a board whose clock has not synced cannot check
// certificate validity dates and must not connect at all rather than connect unvalidated.
#include <cstddef>
#include <cstdint>

namespace fry {

// The earliest epoch a validated TLS session may use: 2020-09-13Z, the same "clearly post-NTP"
// floor src/core/telemetry.cpp:59 already applies before it will send a timestamp. A board whose
// RTC reads 1970 (no NTP yet) is BELOW this and gets no session: BearSSL would compare every
// certificate's validity window against 1970 and reject it anyway (BR_ERR_X509_EXPIRED), but the
// refusal must be ours and explicit, not a side effect.
constexpr uint32_t kTlsMinPlausibleEpoch = 1600000000;

// The compiled trust-anchor set, in the order of src/esp8266/tls_anchors.h.
enum class TlsRoot : uint8_t {
  IsrgX2 = 0,      // hardwareapi.frynetworks.com, fry.farm, dashboard.frynetworks.com
  SectigoE46 = 1,  // github.com
  IsrgX1 = 2,      // release-assets.githubusercontent.com, objects.githubusercontent.com
  Count = 3,
};

// True when `epochSeconds` is a plausible wall-clock time, i.e. NTP has synced.
bool tlsClockUsable(uint32_t epochSeconds);

struct TlsHostRoot {
  const char* host;  // exact hostname as it appears in the compiled URL
  TlsRoot root;      // the anchor that validates that host's chain
};

// Every host this firmware reaches over HTTPS and the anchor that validates it. The chains were
// captured on 2026-10-23 and are written up in tools/gen_tls_anchors.py's header. Exact, case-
// sensitive match: these are compiled string literals, never user input (a user-supplied OTA URL
// exists only in lab builds, where TLS is validated against the same set).
const TlsHostRoot* tlsHostRootTable(size_t* count);

// Fills *root and returns true for a host in the table; false for anything else.
bool tlsRootForHost(const char* host, TlsRoot* root);

}  // namespace fry
